        tips = "Any race can use the learned toy. It is a cosmetic form, not a flying mount or the Night Elf death-release racial. Dig-site locations are personal and rotate. The map's region entries are search areas, not guaranteed toy spawns. Keep learning available Archaeology ranks as you progress; do not confuse fragment cost with required skill.",
        sourceComments = { "https://www.wowhead.com/item=64651#comments:id=1137303" },
        waypoints = {
            {
                mapID = 84,
